/*
 * Rules of the inline mention.
 *
 * The dark choice is light-dark, which follows the nearest scope that sets
 * color-scheme. Rules sit in `@layer components`, so utilities a caller
 * puts on the same element override them.
 */

@layer components {
  .Mention {
    --ck-mention-base-color: color-mix(
      in srgb,
      var(--ck-palette-label-accent) 80%,
      var(--ck-palette-ink) 20%
    );
    --ck-mention-resolved-base-color: light-dark(
      var(--ck-mention-base-color),
      var(--ck-mention-dark-base-color, var(--ck-mention-base-color))
    );
    --ck-mention-color: var(--ck-mention-resolved-base-color);
    padding-inline: calc(var(--spacing) * 0.5);
    color: var(--ck-mention-color);
    font-family: var(--ui-body-font, var(--font-sans));
    font-weight: var(--font-weight-medium);
  }

  .Mention[data-ck-font-weight="inherit"],
  .Mention[data-appearance="underlined-text"] {
    font-weight: inherit;
  }

  .Mention[data-appearance="underlined-text"] .Label {
    text-underline-offset: 2px;
    text-decoration-line: underline;
  }

  .Mention[data-tone="subtle-accent"] {
    --ck-mention-base-color: light-dark(
      color-mix(
        in srgb,
        var(--ck-palette-label-accent) 60%,
        var(--ck-palette-ink) 40%
      ),
      color-mix(
        in srgb,
        var(--ck-palette-label-accent) 40%,
        var(--ck-palette-ink) 60%
      )
    );
  }

  .Mention[data-tone="neutral"] {
    --ck-mention-base-color: var(--ck-palette-ink);
  }

  .Mention[data-layout="inline-flow"] {
    white-space: nowrap;
    padding-inline: 0;
    display: inline;
  }

  .Mention[data-layout="inline-flow"] .IconContainer {
    box-sizing: content-box;
    vertical-align: middle;
    align-items: center;
    height: 1em;
    padding-inline-end: 3px;
    display: inline-flex;
    transform: translateY(calc(0.5ex - 0.5cap));
  }

  .Mention[data-layout="inline-flow"] .IconContainer .Icon {
    top: auto;
    transform: none;
  }

  .Mention[data-layout="inline-flow"] .Label {
    white-space: normal;
  }

  .Mention[data-layout="wrapped-label"] {
    vertical-align: bottom;
    gap: 3px;
    max-width: 100%;
    display: inline-flex;
  }

  .Mention[data-layout="wrapped-label"] .IconContainer {
    flex-shrink: 0;
  }

  .Mention[data-tone="composer-reference"],
  .Mention[data-layout="selection-pill"] {
    --ck-mention-base-color: var(
      --color-text-composer-reference,
      var(--ck-palette-label-accent)
    );
  }

  .Mention[data-layout="selection-pill"] {
    align-items: center;
    gap: calc(var(--spacing) * 1);
    padding-inline: calc(var(--spacing) * 1);
    vertical-align: baseline;
    white-space: nowrap;
    font-weight: inherit;
    display: inline-flex;
  }

  .Mention[data-layout="selection-pill"] .IconContainer {
    --icon-compact-display: none;
    --icon-start-display: contents;
    width: calc(var(--spacing) * 5);
    flex-shrink: 0;
  }

  .Mention[data-layout="selection-pill"] .Icon {
    width: calc(var(--spacing) * 5);
    height: calc(var(--spacing) * 5);
  }

  .Mention[data-layout="selection-pill"] .Label {
    max-width: calc(var(--spacing) * 64);
    overflow-wrap: normal;
    text-overflow: ellipsis;
    white-space: nowrap;
    align-self: baseline;
    overflow: hidden;
  }

  .Mention[data-appearance="pill"] {
    --ck-mention-alpha-08: color-mix(
      in oklab,
      var(--ck-palette-ink) 8%,
      transparent
    );
    max-width: 100%;
    padding-block: calc(var(--spacing) * 0.5);
    padding-inline: calc(var(--spacing) * 1.5);
    border-radius: var(--radius-pill);
    background-color: var(--alpha-08, var(--ck-mention-alpha-08));
    box-decoration-break: clone;
    grid-template-columns: minmax(0, 1fr);
    display: inline-grid;
  }

  :where(td, th) .Mention[data-appearance="pill"] {
    margin-block: calc(var(--spacing) * 0.5);
    padding-block: 0;
  }

  .Mention[data-appearance="pill"] .Label {
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;
  }

  .Mention[data-appearance="pill"] + span {
    white-space: pre-wrap;
  }

  .Mention[data-tone="file-reference"] {
    --ck-mention-base-color: var(
      --color-text-composer-file-reference,
      var(--color-text-composer-reference, var(--ck-palette-label-accent))
    );
  }

  .Mention[data-ck-breakable-url] {
    direction: ltr;
    unicode-bidi: isolate;
    display: inline;
  }

  .Mention[data-ck-breakable-url] .Label {
    word-break: break-all;
  }

  .Mention[data-ck-breakable-url],
  .Mention[text-link-href],
  .Mention[data-ck-inline-url-icon] {
    padding-inline: 0;
  }

  .Mention[data-ck-brand-color] {
    --ck-mention-dark-base-color: color-mix(
      in oklch,
      var(--ck-mention-base-color) 50%,
      var(--ck-palette-ink) 50%
    );
  }

  .Mention[data-interactive] {
    cursor: var(--ck-action-cursor);
  }

  @media (hover: hover) {
    .Mention[data-ck-inline-mention-interactive][data-underline-on-hover]:hover,
    [data-ck-inline-mention-interactive]:hover
      .Mention[data-underline-on-hover] {
      text-decoration-line: var(--ck-mention-hover-decoration, underline);
      text-underline-offset: 2px;
      text-decoration-style: dashed;
      text-decoration-color: currentColor;
      text-decoration-thickness: 0.5px;
    }
  }

  .UnderlinedText .Mention {
    --ck-mention-hover-decoration: none;
    color: inherit;
    font-family: inherit;
    font-weight: inherit;
    vertical-align: baseline;
    white-space: normal;
    padding-inline: 0;
    display: inline;
  }

  .UnderlinedText .Mention .IconContainer {
    display: none;
  }

  .UnderlinedText .Mention .Label {
    color: inherit;
    white-space: normal;
    text-underline-offset: 2px;
    text-decoration-line: underline;
  }

  .UnderlinedText .Text {
    text-underline-offset: 2px;
    text-decoration-line: underline;
  }

  .IconContainer {
    --icon-compact-display: contents;
    --icon-start-display: none;
    height: 1lh;
    position: relative;
  }

  .Icon {
    top: 50%;
    justify-content: center;
    align-items: center;
    display: flex;
    position: relative;
    inset-inline-start: 0;
    transform: translateY(-50%);
  }

  .SlotSizedIconContainer {
    width: calc(var(--spacing) * 4);
  }

  .SlotSizedIcon {
    width: calc(var(--spacing) * 4);
    height: calc(var(--spacing) * 4);
  }

  .Label {
    overflow-wrap: break-word;
    min-width: 0;
  }
}

"use client";

/* oxlint-disable react/no-clone-element, shadcn/no-inline-styles -- InlineMention clones its icon element and the underline-scope child and merges the caller's style object into the mention colour variables. */

import { TooltipHint } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { cloneElement, createElement, isValidElement } from "react";
import type {
  ComponentProps,
  CSSProperties,
  ElementType,
  ReactElement,
  ReactNode,
} from "react";

import styles from "@/components/mention/mention.module.css";

type MentionAppearance = "inline-mention" | "pill" | "underlined-text";

type MentionFontWeight = "inherit" | "medium";

type MentionIconSizing = "authored" | "slot";

type MentionLayout =
  | "inline-flow"
  | "selection-pill"
  | "thumbnail"
  | "wrapped-label";

type MentionTone =
  | "accent"
  | "composer-reference"
  | "file-reference"
  | "neutral"
  | "subtle-accent";

type MentionIcon = ElementType | ReactElement<{ className?: string }>;

type DataAttributes = Readonly<Record<`data-${string}`, string | undefined>>;

type MentionStyle = CSSProperties & Record<`--${string}`, string | undefined>;

interface InlineMentionProps extends Omit<ComponentProps<"span">, "style"> {
  appearance?: MentionAppearance;
  brandColor?: string;
  dataAttributes?: DataAttributes;
  fontWeight?: MentionFontWeight;
  icon?: MentionIcon;
  iconClassName?: string;
  iconSizing?: MentionIconSizing;
  iconSlotProps?: ComponentProps<"span">;
  interactive?: boolean;
  labelClassName?: string;
  layout?: MentionLayout;
  style?: MentionStyle;
  tone?: MentionTone;
  underlineOnHover?: boolean;
}

/** A brand colour or a style colour moves into the two mention variables. */
const resolveStyle = (
  brandColor: string | undefined,
  style: MentionStyle | undefined
): MentionStyle | undefined => {
  if (brandColor === undefined && style?.color === undefined) {
    return style;
  }

  return {
    ...style,
    color: undefined,
    "--ck-mention-base-color": brandColor,
    "--ck-mention-color": style?.color,
  };
};

/** An element gains the icon classes, a component is rendered with them. */
function MentionGlyph({
  className,
  icon,
  iconSizing,
}: {
  className: string | undefined;
  icon: MentionIcon;
  iconSizing: MentionIconSizing;
}) {
  const glyphClass = cn(
    styles.Icon,
    iconSizing === "slot" && styles.SlotSizedIcon,
    className
  );

  if (isValidElement<{ className?: string }>(icon)) {
    return cloneElement(icon, {
      className: cn(glyphClass, icon.props.className),
    });
  }

  return createElement(icon, { className: glyphClass });
}

/** The inline mention span with an icon container and a label. */
function InlineMention({
  appearance = "inline-mention",
  brandColor,
  children,
  className,
  dataAttributes,
  fontWeight = "medium",
  icon,
  iconClassName,
  iconSizing = "slot",
  iconSlotProps,
  interactive = false,
  labelClassName,
  layout = "inline-flow",
  style,
  tone = "accent",
  underlineOnHover = interactive,
  ...props
}: InlineMentionProps) {
  const thumbnail = layout === "thumbnail";

  return (
    <span
      {...props}
      {...dataAttributes}
      className={cn(
        styles.Mention,
        thumbnail && "inline-flex px-1 py-0 align-middle",
        className
      )}
      data-appearance={appearance}
      data-ck-brand-color={brandColor === undefined ? undefined : ""}
      data-ck-font-weight={fontWeight}
      data-ck-inline-mention-interactive={interactive ? "" : undefined}
      data-interactive={interactive ? "" : undefined}
      data-layout={layout}
      data-tone={tone}
      data-underline-on-hover={underlineOnHover ? "" : undefined}
      style={resolveStyle(brandColor, style)}
    >
      {icon === undefined || icon === null ? null : (
        <span
          {...iconSlotProps}
          className={cn(
            styles.IconContainer,
            iconSizing === "slot" &&
              !thumbnail &&
              styles.SlotSizedIconContainer,
            thumbnail && "inline-flex size-8 overflow-hidden rounded-full"
          )}
        >
          <MentionGlyph
            className={iconClassName}
            icon={icon}
            iconSizing={iconSizing}
          />
        </span>
      )}
      <span className={cn(styles.Label, thumbnail && "hidden", labelClassName)}>
        {children}
      </span>
    </span>
  );
}

/** An underlined-text appearance marks its child with the underline scope. */
function UnderlinedMentionScope({
  appearance,
  children,
}: {
  appearance: MentionAppearance;
  children: ReactElement<{ className?: string }>;
}) {
  if (appearance !== "underlined-text") {
    return children;
  }

  return cloneElement(children, {
    className: cn(children.props.className, styles.UnderlinedText),
  });
}

/** Plain text that the underline scope underlines. */
function MentionText({ children }: { children?: ReactNode }) {
  return <span className={styles.Text}>{children}</span>;
}

interface MentionPillProps {
  ariaLabel?: string;
  brandColor?: string;
  className?: string;
  dataAttributes?: DataAttributes;
  icon?: MentionIcon;
  iconClassName?: string;
  interactive?: boolean;
  layout?: MentionLayout;
  role?: ComponentProps<"span">["role"];
  style?: MentionStyle;
  tabIndex?: number;
  text: ReactNode;
  textClassName?: string;
  tooltipBodyClassName?: string;
  tooltipText?: ReactNode;
}

/** An InlineMention that gains a tooltip when `tooltipText` is given. */
function MentionPill({
  ariaLabel,
  brandColor,
  className,
  dataAttributes,
  icon,
  iconClassName,
  interactive = false,
  layout,
  role,
  style,
  tabIndex,
  text,
  textClassName,
  tooltipBodyClassName,
  tooltipText,
}: MentionPillProps) {
  const mention = (
    <InlineMention
      aria-label={ariaLabel}
      brandColor={brandColor}
      className={className}
      dataAttributes={dataAttributes}
      icon={icon}
      iconClassName={iconClassName}
      interactive={interactive}
      labelClassName={textClassName}
      layout={layout}
      role={role}
      style={style}
      tabIndex={tabIndex}
    >
      {text}
    </InlineMention>
  );

  if (tooltipText === undefined || tooltipText === null) {
    return mention;
  }

  return (
    <TooltipHint
      cloneCustomTrigger
      content={tooltipText}
      tooltipBodyClassName={tooltipBodyClassName}
    >
      {mention}
    </TooltipHint>
  );
}

export { InlineMention, MentionPill, MentionText, UnderlinedMentionScope };

export type {
  InlineMentionProps,
  MentionAppearance,
  MentionIcon,
  MentionLayout,
  MentionPillProps,
  MentionTone,
};
